-- Public HOT DTO exposes only paid, unexpired promotion profiles; no billing identity.
create function public.active_hot_creators() returns table(creator_id text,profile jsonb,expires_at timestamptz) language sql stable security definer set search_path=public as $$ select c.id,c.profile,max(e.expires_at) from creators c join entitlements e on e.owner_id=c.owner_id join orders o on o.id=e.order_id where c.published and e.sku='creator_hot' and e.starts_at<=now() and e.expires_at>now() and o.status='paid' group by c.id,c.profile order by max(e.expires_at) desc limit 6; $$;
create function public.moderate_entity(p_kind text,p_id text,p_published boolean) returns void language plpgsql security definer set search_path=public as $$ begin if not is_admin() then raise exception 'forbidden';end if;if p_kind='creator' then update creators set published=p_published where id=p_id;elsif p_kind='campaign' and not p_published then update campaigns set status='closed' where id=p_id::uuid;else raise exception 'invalid operation';end if;insert into audit_log(actor_id,entity_id,action) values(auth.uid(),p_id,'moderate:'||p_kind||':'||p_published::text);end $$;
revoke all on function public.moderate_entity(text,text,boolean) from public,anon;grant execute on function public.moderate_entity(text,text,boolean) to authenticated;
create table public.proposal_reads(proposal_id uuid not null references proposals(id),user_id uuid not null references profiles(id),last_read_at timestamptz not null default now(),primary key(proposal_id,user_id));
alter table proposal_reads enable row level security;
create policy reads_own on proposal_reads for all using(user_id=auth.uid()) with check(user_id=auth.uid() and exists(select 1 from proposals p where p.id=proposal_id and auth.uid() in (p.brand_id,p.creator_user_id)));
